export const multiPathVerifier = (reasoningPaths) => {
  const verifyPaths = (paths) => {
    return paths.map(path => {
      const counterfactualAnalysis = path.steps.map(step => ({ ...step, counterfactual: !step.valid }));
      return { ...path, verified: counterfactualAnalysis.every(step => step.counterfactual === false) };
    });
  };
  return verifyPaths(reasoningPaths);
};